import { decoratedNavContains, decoratedNavSections, findDecoratedNavPage, } from './decoratedNavTree.js';
const nav = {
    tabs: [
        {
            tab: 'Guides',
            groups: [
                { group: 'Start', pages: [{ href: '/guides/intro', title: 'Intro' }] },
                { group: 'More', pages: [{ href: '/guides/deploy', title: 'Deploy', mode: 'custom' }] },
            ],
        },
        { tab: 'API', pages: [{ href: '/api/overview', title: 'Overview' }] },
    ],
};
describe('decoratedNavContains', () => {
    it('finds pages through divisions and groups, ignoring slashes and /index', () => {
        expect(decoratedNavContains(nav, '/guides/deploy')).toBe(true);
        expect(decoratedNavContains(nav, 'guides/deploy/')).toBe(true);
        expect(decoratedNavContains(nav, '/api/overview/index')).toBe(true);
        expect(decoratedNavContains(nav, '/nowhere')).toBe(false);
    });
});
describe('findDecoratedNavPage', () => {
    it('returns the page title and mode', () => {
        expect(findDecoratedNavPage(nav, '/guides/deploy')).toEqual({
            title: 'Deploy',
            mode: 'custom',
        });
        expect(findDecoratedNavPage(nav, '/api/overview')).toEqual({
            title: 'Overview',
            mode: undefined,
        });
        expect(findDecoratedNavPage(nav, '/nowhere')).toBeNull();
    });
});
describe('decoratedNavSections', () => {
    it('returns the division whose own pages hold the path', () => {
        const sections = decoratedNavSections(nav, '/guides/intro');
        expect(sections).toHaveLength(1);
        expect(sections[0]).toBe(nav.tabs[0]);
        expect(decoratedNavSections(nav, '/nowhere')).toEqual([]);
    });
    it('returns the root for a flat nav', () => {
        const flat = {
            pages: [
                { href: '/a', title: 'A' },
                { href: '/b', title: 'B' },
            ],
        };
        expect(decoratedNavSections(flat, '/a')).toEqual([flat]);
    });
    it('passes through a menu item split by version to the version that owns the page', () => {
        const v3 = {
            version: 'v3',
            groups: [{ group: 'Start', pages: [{ href: '/studio/v3', title: 'Overview' }] }],
        };
        const v1 = { version: 'v1', pages: [{ href: '/studio/v1', title: 'v1' }] };
        const menuNav = {
            tabs: [{ tab: 'Studio', menu: [{ item: 'Studio', versions: [v3, v1] }] }],
        };
        expect(decoratedNavSections(menuNav, '/studio/v3')).toEqual([v3]);
        expect(decoratedNavSections(menuNav, '/studio/v1')).toEqual([v1]);
    });
});
